import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷五·13","description":"易小帖 - 卷五·13","frontmatter":{"title":"卷五·13","description":"易小帖 - 卷五·13"},"headers":[],"relativePath":"classics/yixiaotie/135.md","filePath":"classics/yixiaotie/135.md"}'),o={name:"classics/yixiaotie/135.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷五·13",tabindex:"-1"},[r("卷五·13 "),e("a",{class:"header-anchor",href:"#卷五·13","aria-label":"Permalink to “卷五·13”"},"​")],-1),e("p",null,"昨來所訊，病中不能閱，並不能一一裁復。越二日，家姪文輝檢及舉易系一節，謂此經改過，何緣又訊，豈前所付易是舊未改時本耶。僕見大驚，且仰天呼曰：天復生是人耶！噫乎！吾學從此興矣。當某註易成時，已齋宿告先仲兄主前，將付梓人，而獨於此節凡兩換稿，而終不自愜，然已見様本矣。既而，兒子從南昌寓家人信，以為此節似申言揲筮之意，因幡然改之，今足下又見及此何其相契之深若是也。豈非羲文三聖，嘿有以啟之也耶。足下觀書如觀流水，寓目即駛，而又灼灼若觀火，此非輓近學儒所可到者。《論語》曰：德不孤，必有隣。吾既得隣，古學豈孤乎。勉矣。改易二葉，併發惟查核不具。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
